const parseMaybe = (value, fallback) => {
  if (value === null || value === undefined) return fallback;
  if (typeof value === 'string') {
    try {
      return JSON.parse(value);
    } catch {
      return fallback;
    }
  }
  return value;
};

const normalize = (value = '') => String(value)
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/[^\p{L}\p{N}\s]/gu, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const scoreMatch = (text, source) => {
  const normalizedSource = normalize(source);
  if (!normalizedSource) return 0;

  const phrases = normalizedSource
    .split(/[;,|\n]/)
    .map((item) => item.trim())
    .filter(Boolean);

  let best = 0;

  for (const phrase of phrases) {
    if (text === phrase) {
      best = Math.max(best, 100);
      continue;
    }

    if (text.includes(phrase)) {
      best = Math.max(best, 80 + Math.min(phrase.split(' ').length, 5));
      continue;
    }

    const tokens = phrase.split(' ').filter((token) => token.length > 1);
    if (!tokens.length) continue;

    const matched = tokens.filter((token) => text.includes(token)).length;
    if (matched === tokens.length) {
      best = Math.max(best, 60 + matched);
    } else if (matched > 0) {
      best = Math.max(best, 20 + matched);
    }
  }

  return best;
};

const text = $json.text || '';
const phone = $json.phone || '';
const instance = $json.instance || $env.EVOLUTION_INSTANCE || 'teste-atendimento';
const textNorm = normalize(text);
const bot = parseMaybe($json.bot, {});
const actions = parseMaybe($json.actions, []);
const faqs = parseMaybe($json.faqs, []);

// Verifica se veio do nó Normalize indicando mídia
const isMedia = $node["Normalize"].json.is_media === true;

let winner = null;

if (!isMedia) {
  for (const action of actions) {
    const score = scoreMatch(textNorm, action.gatilho || action.nome || '');
    if (!winner || score > winner.score) {
      winner = {
        score,
        type: 'action',
        item: action,
      };
    }
  }

  for (const faq of faqs) {
    const score = Math.max(
      scoreMatch(textNorm, faq.palavras_chave || ''),
      scoreMatch(textNorm, faq.pergunta || '')
    );

    if (!winner || score > winner.score) {
      winner = {
        score,
        type: 'faq',
        item: faq,
      };
    }
  }
}

let reply = '';
let matchedType = 'fallback';
let matchedId = null;

if (isMedia) {
  matchedType = 'media_warning';
  reply = "Desculpe, sou um assistente virtual e no momento só consigo responder a mensagens de texto. Por favor, envie sua dúvida por texto escrito.";
} else if (winner && winner.score >= 25) {
  matchedType = winner.type;
  matchedId = winner.item.id || null;
  reply = winner.type === 'action'
    ? (winner.item.resposta_fixa || '')
    : (winner.item.resposta || '');
}

if (!reply) {
  const faqHints = faqs
    .slice(0, 3)
    .map((faq) => '- ' + faq.pergunta)
    .join('\n');

  reply = [
    `Ola! Sou ${bot.nome || 'o bot de atendimento'}.`,
    faqHints ? 'Posso ajudar com:\n' + faqHints : 'Posso ajudar com horario, endereco, documentos e encaminhamento para atendente.',
    'Escreva sua duvida com poucas palavras ou digite atendente.'
  ].join('\n\n');
}

return [{
  json: {
    phone,
    text,
    instance,
    bot,
    matched_type: matchedType,
    matched_id: matchedId,
    reply_text: reply
  }
}];
